//! Runtime support for Zig code generated by `zant-tsx` from `.tsx`
//! components (`docs/tsx.md`). Hand-written Zig code rarely needs it.
const std = @import("std");
const ui = @import("ui.zig");

/// String.prototype helpers for generated TSX code.
pub const strings = @import("tsx_strings.zig");
/// The entry of a TS + TSX app (the generated `main.zig`).
pub const app = @import("tsx_app.zig");
/// `KeyEvent` in TSX (`useKeyDown`).
pub const KeyEvent = app.KeyEvent;
/// JavaScript numeric built-ins for generated TSX code.
pub const builtins = @import("tsx_builtins.zig");
/// Nested `<Text>` spans and inline `<Link>`s.
pub const text = @import("tsx_text.zig");

/// `Uint8Array` in TSX. In a Zig file imported by TSX, write `tsx.Bytes` (not
/// `[]const u8`, which is a string there) for parameters and results that are
/// bytes: `pub fn readImage() ?zant.tsx.Bytes`.
pub const Bytes = []const u8;

/// Heap memory of string state; it lives as long as the state value.
const allocator = std.heap.smp_allocator;

/// String state (`useState<string>`): starts as a literal and owns a copy
/// of every later value.
pub const String = struct {
    initial: []const u8 = "",
    owned: ?[]u8 = null,

    pub fn get(self: *const String) []const u8 {
        return self.owned orelse self.initial;
    }

    /// Replaces the value with a copy of `value` (which may alias the
    /// current one).
    pub fn set(self: *String, value: []const u8) void {
        const copy = allocator.dupe(u8, value) catch @panic("Zant UI: out of memory while setting string state");
        if (self.owned) |old| allocator.free(old);
        self.owned = copy;
    }

    pub fn deinit(self: *String) void {
        if (self.owned) |old| allocator.free(old);
        self.owned = null;
    }
};

/// Template literals, string `+` and JSX text with expressions: formatted
/// into the frame arena (valid until the next frame, like every node).
pub fn fmt(comptime format: []const u8, args: anytype) []const u8 {
    return builtins.format(format, args);
}

/// Children with conditional entries (`{cond && <X/>}`): drops the nulls.
pub fn nodes(items: []const ?ui.Node) []const ui.Node {
    const out = ui.frameAllocator().alloc(ui.Node, items.len) catch
        @panic("Zant UI: out of memory while building children");
    var n: usize = 0;
    for (items) |item| {
        if (item) |node| {
            out[n] = node;
            n += 1;
        }
    }
    return out[0..n];
}

test "string state owns its values" {
    var s = String{ .initial = "Zant" };
    defer s.deinit();
    try std.testing.expectEqualStrings("Zant", s.get());
    s.set("UI");
    try std.testing.expectEqualStrings("UI", s.get());
    s.set(s.get()[0..1]); // aliasing the current value
    try std.testing.expectEqualStrings("U", s.get());
}

test "nodes drops null children" {
    ui.beginFrame();
    defer ui.endFrame();
    const a = ui.text("a", .{});
    const b = ui.text("b", .{});
    const out = nodes(&.{ a, null, b, null });
    try std.testing.expectEqual(@as(usize, 2), out.len);
    try std.testing.expectEqual(b.element, out[1].element);
    try std.testing.expectEqualStrings("x=3 on", fmt("x={d} {s}", .{ 3, "on" }));
}

/// Immutable composite state retains every previous value until the next render.
/// `allocator` is configurable for tests; generated state uses the process allocator.
pub fn State(comptime T: type) type {
    return struct {
        const Self = @This();
        initial: T,
        allocator: std.mem.Allocator = std.heap.smp_allocator,
        value: ?T = null,
        arena: ?std.heap.ArenaAllocator = null,
        retired: std.ArrayList(std.heap.ArenaAllocator) = .empty,

        pub fn get(self: *const Self) T {
            return self.value orelse self.initial;
        }

        /// Copy before retiring the old arena, so aliasing updates remain valid.
        pub fn set(self: *Self, value: T) void {
            var next = std.heap.ArenaAllocator.init(self.allocator);
            const copy = deepCopy(T, next.allocator(), value) catch @panic("Zant UI: state allocation failed");
            if (self.arena) |previous| {
                self.retired.append(self.allocator, previous) catch @panic("Zant UI: state allocation failed");
            }
            self.arena = next;
            self.value = copy;
        }

        /// Called at the start of render, after callbacks from the old frame finish.
        pub fn sweep(self: *Self) void {
            for (self.retired.items) |*previous| previous.deinit();
            self.retired.clearRetainingCapacity();
        }

        pub fn deinit(self: *Self) void {
            self.sweep();
            self.retired.deinit(self.allocator);
            if (self.arena) |*current| current.deinit();
            self.arena = null;
            self.value = null;
            self.retired = .empty;
        }
    };
}

/// A TS `number` passed to an integer field (`page={n}`): truncated toward
/// zero and clamped to `T`'s range (NaN is 0).
pub fn toInt(comptime T: type, value: anytype) T {
    const v: f64 = @floatCast(value);
    if (std.math.isNan(v)) return 0;
    const lo: f64 = @floatFromInt(std.math.minInt(T));
    const hi: f64 = @floatFromInt(std.math.maxInt(T));
    return @intFromFloat(std.math.clamp(@trunc(v), lo, hi));
}

test toInt {
    try std.testing.expectEqual(@as(usize, 2), toInt(usize, @as(f64, 2.9)));
    try std.testing.expectEqual(@as(usize, 0), toInt(usize, @as(f64, -3)));
    try std.testing.expectEqual(@as(i32, -3), toInt(i32, @as(f64, -3.7)));
    try std.testing.expectEqual(@as(u8, 255), toInt(u8, @as(f64, 1e9)));
    try std.testing.expectEqual(@as(u8, 0), toInt(u8, std.math.nan(f64)));
}

/// `str.length` with TypeScript's meaning: UTF-16 code units, not bytes
/// (`"周报".length` is 2, an emoji counts 2). Every byte that starts a code
/// point counts one, and a 4-byte sequence (outside the BMP) one more.
pub fn utf16Length(s: []const u8) usize {
    var units: usize = 0;
    for (s) |b| units += @as(usize, @intFromBool(b & 0xC0 != 0x80)) + @intFromBool(b >= 0xF0);
    return units;
}

test utf16Length {
    try std.testing.expectEqual(@as(usize, 0), utf16Length(""));
    try std.testing.expectEqual(@as(usize, 5), utf16Length("hello"));
    try std.testing.expectEqual(@as(usize, 6), utf16Length("周五前交周报"));
    try std.testing.expectEqual(@as(usize, 3), utf16Length("📌 "));
}

/// The instance id of a stateful child component (`ui.localState`): the
/// parent's id (the root's is 0) mixed with the component's name and its key
/// (string or number) or call-site number.
pub fn childId(parent: u64, comptime name: []const u8, key: anytype) u64 {
    const named = parent ^ comptime std.hash.Wyhash.hash(0, name);
    return switch (@typeInfo(@TypeOf(key))) {
        .float, .comptime_float => ui.childId(named, @as(u64, @bitCast(@as(f64, key)))),
        else => ui.childId(named, key),
    };
}

/// The instance id of a key-less stateful child: numbered by call site, never
/// equal to a keyed sibling's `childId`.
pub fn siteId(parent: u64, comptime name: []const u8, comptime site: u32) u64 {
    return ui.childId(parent ^ comptime std.hash.Wyhash.hash(1, name), site);
}

/// Frees a component's local state slot: every field with a `deinit`.
pub fn deinitFields(value: anytype) void {
    const T = @TypeOf(value.*);
    inline for (@typeInfo(T).@"struct".field_names) |name| {
        const F = @FieldType(T, name);
        if (@typeInfo(F) == .@"struct" and @hasDecl(F, "deinit")) @field(value, name).deinit();
    }
}

const hooks = @import("tsx_hooks.zig");
pub const Deps = hooks.Deps;
pub const Memo = hooks.Memo;
pub const Effect = hooks.Effect;
pub const deepEql = hooks.deepEql;

/// `createStore<T>(initial)`: app state shared by components and files. Values
/// are copied in like `State`; a change rebuilds every window.
pub fn Store(comptime T: type) type {
    return struct {
        const Self = @This();
        state: State(T),

        pub fn get(self: *const Self) T {
            return self.state.get();
        }

        /// `useStore`: frees the values earlier changes replaced (their frames
        /// are gone), then reads.
        pub fn read(self: *Self) T {
            self.state.sweep();
            return self.state.get();
        }

        pub fn set(self: *Self, value: T) void {
            self.state.set(value);
            ui.requestRebuild();
            @import("ui_runtime.zig").Runtime.invalidateAll();
        }

        /// Replaces the fields listed in `changes` (a shallow merge).
        pub fn update(self: *Self, changes: anytype) void {
            var next = self.get();
            inline for (@typeInfo(@TypeOf(changes)).@"struct".field_names) |name| {
                @field(next, name) = @field(changes, name);
            }
            self.set(next);
        }
    };
}

test Store {
    const Settings = struct { dark: bool, name: []const u8 };
    var store: Store(Settings) = .{ .state = .{ .initial = .{ .dark = false, .name = "a" } } };
    defer store.state.deinit();
    var name = [_]u8{ 'b', 'c' };
    store.update(.{ .name = @as([]const u8, &name) });
    name[0] = 'x';
    try std.testing.expectEqualStrings("bc", store.read().name);
    store.update(.{ .dark = true });
    try std.testing.expect(store.get().dark);
    try std.testing.expectEqualStrings("bc", store.get().name);
}

/// Only immutable value types produced by the compiler participate in state copies.
pub fn deepCopy(comptime T: type, a: std.mem.Allocator, value: T) std.mem.Allocator.Error!T {
    return switch (@typeInfo(T)) {
        .pointer => |pointer| blk: {
            if (pointer.size != .slice) @compileError("TSX state supports slices, not pointers");
            const result = try a.alloc(pointer.child, value.len);
            for (value, result) |item, *out| out.* = try deepCopy(pointer.child, a, item);
            break :blk result;
        },
        .@"struct" => |structure| blk: {
            var result = value;
            inline for (structure.field_names, structure.field_types) |name, F| {
                @field(result, name) = try deepCopy(F, a, @field(value, name));
            }
            break :blk result;
        },
        .optional => |optional| if (value) |item| try deepCopy(optional.child, a, item) else null,
        .array => |array| blk: {
            var result: T = undefined;
            for (value, &result) |item, *out| out.* = try deepCopy(array.child, a, item);
            break :blk result;
        },
        .@"enum", .int, .float, .bool => value,
        else => @compileError("unsupported TSX state type " ++ @typeName(T)),
    };
}

/// Allocate a value capture for a callback in the current frame.
pub fn capture(value: anytype) *@TypeOf(value) {
    const pointer = ui.frameAllocator().create(@TypeOf(value)) catch @panic("Zant UI: capture allocation failed");
    pointer.* = value;
    return pointer;
}

/// Concatenate immutable slices into one frame-owned result.
pub fn concat(comptime T: type, parts: []const []const T) []const T {
    var count: usize = 0;
    for (parts) |part| count += part.len;
    const result = alloc(T, count);
    var offset: usize = 0;
    for (parts) |part| {
        @memcpy(result[offset..][0..part.len], part);
        offset += part.len;
    }
    return result;
}

pub fn alloc(comptime T: type, count: usize) []T {
    return ui.frameAllocator().alloc(T, count) catch @panic("Zant UI: frame allocation failed");
}

/// Numeric indexing checks negative, fractional, nonfinite, and out-of-range values.
/// Invalid indexes panic instead of silently truncating JavaScript numbers.
pub fn index(value: anytype) usize {
    const T = @TypeOf(value);
    if (@typeInfo(T) == .float or @typeInfo(T) == .comptime_float) {
        if (!std.math.isFinite(value) or value < 0 or @trunc(value) != value) @panic("invalid TSX index");
        return @intFromFloat(value);
    }
    return @intCast(value);
}

/// Slice endpoints follow JS clamping and negative-offset rules.
pub fn sliceIndex(value: anytype, length: usize) usize {
    const number: f64 = if (@typeInfo(@TypeOf(value)) == .int) @floatFromInt(value) else value;
    if (std.math.isNan(number)) return 0;
    const len: f64 = @floatFromInt(length);
    const clamped = @min(len, @max(0, if (number < 0) len + @trunc(number) else @trunc(number)));
    return @intFromFloat(clamped);
}

pub fn join(items: []const []const u8, separator: []const u8) []const u8 {
    return std.mem.join(ui.frameAllocator(), separator, items) catch @panic("Zant UI: join allocation failed");
}

test "composite state copies nested strings and keeps retired snapshots until sweep" {
    const Item = struct { title: []const u8, notes: []const ?[]const u8 };
    var state = State([]const Item){ .initial = &.{}, .allocator = std.testing.allocator };
    defer state.deinit();
    var title = [_]u8{ 'o', 'l', 'd' };
    state.set(&.{.{ .title = &title, .notes = &.{ "nested", null } }});
    title[0] = 'x';
    const snapshot = state.get();
    state.set(snapshot);
    state.set(&.{});
    try std.testing.expectEqualStrings("old", snapshot[0].title);
    try std.testing.expectEqualStrings("nested", snapshot[0].notes[0].?);
    try std.testing.expectEqual(@as(usize, 2), state.retired.items.len);
    state.sweep();
    try std.testing.expectEqual(@as(usize, 0), state.retired.items.len);
    for (0..1000) |_| {
        state.set(&.{.{ .title = "cycle", .notes = &.{null} }});
        state.set(state.get());
        state.sweep();
    }
}

/// Compile-time constants use array concatenation without a frame allocator.
pub fn constantConcat(comptime T: type, comptime parts: anytype) [constantLength(parts)]T {
    var result: [constantLength(parts)]T = undefined;
    var offset: usize = 0;
    inline for (parts) |part| {
        @memcpy(result[offset..][0..part.len], part);
        offset += part.len;
    }
    return result;
}

fn constantLength(comptime parts: anytype) usize {
    comptime var length: usize = 0;
    inline for (parts) |part| length += part.len;
    return length;
}

test "optional object state preserves null and enum values without borrowing strings" {
    const Item = struct { name: []const u8, mode: enum { active, done }, child: ?[]const u8 };
    var state = State(?Item){ .initial = null, .allocator = std.testing.allocator };
    defer state.deinit();
    var buffer = [_]u8{ 'A', 'B' };
    state.set(.{ .name = &buffer, .mode = .active, .child = &buffer });
    buffer[0] = 'X';
    const previous = state.get().?;
    state.set(null);
    try std.testing.expect(state.get() == null);
    try std.testing.expectEqualStrings("AB", previous.name);
    try std.testing.expectEqualStrings("AB", previous.child.?);
    try std.testing.expectEqual(.active, previous.mode);
    state.sweep();
}

test "all-null slice state preserves its length" {
    var state = State([]const ?u8){ .initial = &.{}, .allocator = std.testing.allocator };
    defer state.deinit();
    state.set(&.{ null, null });
    try std.testing.expectEqual(@as(usize, 2), state.get().len);
    state.set(state.get());
    state.sweep();
    try std.testing.expectEqual(@as(usize, 2), state.get().len);
}

test "empty object state can be replaced and swept" {
    var state = State(struct {}){ .initial = .{}, .allocator = std.testing.allocator };
    defer state.deinit();
    state.set(.{});
    state.set(state.get());
    state.sweep();
    try std.testing.expectEqual(@as(usize, 0), state.retired.items.len);
}

/// A null-only TS value uses ?u8 in memory; preserve evaluation when lifting it to ?T.
pub fn nullAs(comptime T: type, value: ?u8) ?T {
    _ = value;
    return null;
}

/// Compare a null-only value while preserving argument evaluation order.
pub fn nullEqual(comptime left_null: bool, a: anytype, b: anytype) bool {
    const ignored = if (left_null) a else b;
    const optional = if (left_null) b else a;
    _ = ignored;
    return optional == null;
}

test "null-only values lift and compare with unrelated nullable types" {
    const nil: ?u8 = null;
    try std.testing.expect(nullAs(ui.Node, nil) == null);
    try std.testing.expect(!nullEqual(true, nil, @as(?[]const u8, "text")));
    try std.testing.expect(!nullEqual(false, @as(?[]const u8, "text"), nil));
    try std.testing.expect(nullEqual(true, nil, @as(?[]const u8, null)));
}

/// A typed callback prop of a TSX child component (`onToggle: (id: number) =>
/// void` → `Callback(fn (u32) void)`): a context pointer and an adapter taking
/// the arguments as a tuple. Keyed by a function type, which is the same type
/// in every file, so callbacks cross generated modules.
pub fn Callback(comptime F: type) type {
    const Args = std.meta.ArgsTuple(F);
    return struct {
        ctx: *anyopaque,
        func: *const fn (*anyopaque, Args) void,

        pub fn call(self: @This(), args: Args) void {
            self.func(self.ctx, args);
        }
    };
}

/// Binds `f(ctx, args...)` as a `Callback(F)`.
pub fn callback(comptime F: type, ctx: anytype, comptime f: anytype) Callback(F) {
    const Ctx = @TypeOf(ctx);
    const Args = std.meta.ArgsTuple(F);
    const Adapter = struct {
        fn call(raw: *anyopaque, args: Args) void {
            const typed: Ctx = @ptrCast(@alignCast(raw));
            @call(.auto, f, .{typed} ++ args);
        }
    };
    return .{ .ctx = @ptrCast(ctx), .func = Adapter.call };
}

test "typed callbacks pass their arguments through" {
    const Counter = struct {
        total: f64 = 0,
        fn add(self: *@This(), amount: f64, times: u32) void {
            self.total += amount * @as(f64, @floatFromInt(times));
        }
    };
    var counter = Counter{};
    const cb = callback(fn (f64, u32) void, &counter, Counter.add);
    // the same callback type wherever it is spelled
    try std.testing.expect(@TypeOf(cb) == Callback(fn (f64, u32) void));
    cb.call(.{ 1.5, 2 });
    cb.call(.{ 1, 1 });
    try std.testing.expectEqual(@as(f64, 4), counter.total);
}
